function dialog(title,content){disposeMaps();returnFocus=document.activeElement;if(!$('modal')){const box=document.createElement('div');box.id='modal';$('content').append(box);}$('modal').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle" tabindex="-1"><div class="modal-head"><h3 id="dialogTitle">${esc(title)}</h3><button type="button" id="closeModal" aria-label="بستن">×</button></div>${content}<div id="formError" class="error" role="alert" hidden></div></section></div>`;$('closeModal').onclick=closeDialog;$('modal').querySelector('section').focus();}
