document.addEventListener('keydown',e=>{const modal=$('modal')?.querySelector('[role="dialog"]');if(!modal)return;if(e.key==='Escape')closeDialog();if(e.key==='Tab'){const items=[...modal.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&!x.hidden);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
